import React, { useState } from "react";
import { createExamCenter } from "../services/api";

const AddExamCenter = () => {
  const [name, setName] = useState("");
  const [location, setLocation] = useState("");
  const [status, setStatus] = useState("active");
  const [contactNumber, setContactNumber] = useState("");

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      await createExamCenter({ name, location, status, contactNumber });
      alert("Exam Center created successfully!");
      setName("");
      setLocation("");
      setStatus("active");
      setContactNumber("");
    } catch (error) {
      console.error(error);
      alert("Failed to create exam center");
    }
  };

  return (
    <div>
      <h2>Add Exam Center</h2>
      <form onSubmit={handleSubmit}>
        <input
          type="text"
          placeholder="Name"
          value={name}
          onChange={(e) => setName(e.target.value)}
          required
        />
        <input
          type="text"
          placeholder="Location"
          value={location}
          onChange={(e) => setLocation(e.target.value)}
          required
        />
        <select value={status} onChange={(e) => setStatus(e.target.value)}>
          <option value="active">Active</option>
          <option value="inactive">Inactive</option>
        </select>
        <input
          type="text"
          placeholder="Contact Number"
          value={contactNumber}
          onChange={(e) => setContactNumber(e.target.value)}
          required
        />
        <button type="submit">Add Exam Center</button>
      </form>
    </div>
  );
};

export default AddExamCenter;
